/**
 * robots.txt (generated by Next.js Metadata API)
 * ==============================================
 * Serves /robots.txt. The whole site is crawlable, and AI answer-engine
 * crawlers are explicitly welcomed: if GPTBot, PerplexityBot, ClaudeBot, or
 * Google-Extended were blocked, those platforms could not cite VADO at all.
 */

import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/site";

// AI answer-engine and search crawlers we explicitly allow. Listed for clarity
// and to guard against a future blanket Disallow slipping in.
const AI_CRAWLERS = [
  "GPTBot", // OpenAI / ChatGPT training + browsing
  "ChatGPT-User", // ChatGPT live browsing
  "OAI-SearchBot", // ChatGPT search index
  "PerplexityBot", // Perplexity index
  "Perplexity-User", // Perplexity live fetch
  "ClaudeBot", // Anthropic / Claude
  "anthropic-ai", // Anthropic (legacy agent)
  "Claude-Web", // Claude web browsing
  "Google-Extended", // Gemini + Google AI Overviews
  "Applebot-Extended", // Apple Intelligence
  "Bingbot", // Microsoft Copilot (via Bing)
  "CCBot", // Common Crawl (feeds many open datasets)
];

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      { userAgent: "*", allow: "/" },
      { userAgent: AI_CRAWLERS, allow: "/" },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
    host: SITE_URL,
  };
}
